def icon(name):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+icons[name]+'</svg>'
def select(text):return f'<div class="select">{text}<span class="chev">⌄</span></div>'
def toggle(on=False):return '<div class="toggle '+('on' if on else '')+'"><i></i></div>'
def row(title,value,help='',last=False):return f'<div class="row"><div><div class="label">{title}</div>'+ (f'<p>{help}</p>' if help else '')+f'</div><div class="value">{value}</div></div>'
def nav(active=0):return ''.join(f'<div class="navitem {"active" if i==active else ""}">{icon(n)}<span>{t}</span></div>' for i,(n,t) in enumerate([('page','Page layout'),('image','Image settings'),('file','File settings')]))
def sheet():return '<div class="sheet"><div class="mark tl"></div><div class="mark tr"></div>'+''.join('<div class="mini-card"></div>' for _ in range(8))+'<div class="mark bl"></div><span>LETTER · 8 POSITIONS</span></div>'
