combined_style = styleA + preview_css + '.prefs{width:1300px}.prefbody{grid-template-columns:208px minmax(0,1fr) 264px}.prefs .content{padding:25px 28px}.prefs .preview{padding:30px 24px}.prefs .sheet{margin-top:12px;margin-bottom:30px}.prefs .select{min-width:182px}'
(out/'04-preferences-preview.html').write_text(f'<!doctype html><meta charset="utf-8"><title>Preferences with page preview</title><style>{base}{combined_style}</style><div class="caption">Refined concept<strong>Preferences window + page preview</strong></div><div class="canvas"><div class="app">{combined}</div></div>')
